code:
// The app-owned STUDIO sessions (#3357) — the one place that describes the designer / librarian /
// architect singleton sessions: their stable pane id, role, workspace-setup command, persona, tunnel
// roster entry, and the page they dock on. Pure + React-free so the registry is unit-testable and can be
// read from the store slice, the mount, the page docks, and the Glance wiring without a cycle.
//
// WHY A REGISTRY: before #3357 each studio owned a bespoke `use*Terminal` hook that mounted its OWN xterm
// via `useScreenSession`. That terminal could not be re-parented, so the Glance graph could not morph a
// studio node into its live session (only the debugger, already on TerminalHost, could). All three now
// launch through the SHARED TerminalHost like every fleet terminal — which means their launch inputs must
// live as DATA the generic launch path (`TerminalView` + `buildSessionSettings`) reads, not as a bespoke
// `pty_create` call. This file is that data.
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import {
  designerSessionId,
  librarianSessionId,
  isStudioTech,
  studioPaneTech,
  type StudioAxis,
  TEAMS_STUDIO_SESSION_ID,
  SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
} from "@/shared/lib/session/systemSessions";

export type { StudioAxis };
export { EMPTY_STUDIO_AXIS, studioAxis } from "@/shared/lib/session/systemSessions";

/** A studio session id: a studio KIND, plus that kind's technology when its store is partitioned
 *  (`designerReact`, `librarianRust`, `architect`).
 *
 *  A STRING since `the-studio-session-set-is-derived-not-declared`, where it was a union of eight
 *  literals. The union's own doc argued it had to be one — "a runtime-materialised session would have
 *  none of those" — and the reason the argument failed is that the eight literals were never eight
 *  independent facts. They were five KINDS crossed with the technologies two of those kinds' stores
 *  happen to hold, and the crossing was being retyped by hand. That is how `librarianPython` came to
 *  exist for a technology with no python record anywhere in the repo.
 *
 *  What the union really bought was that a TYPO in an id is a build error. That is preserved, and by a
 *  stricter instrument: {@link studioSessionDef} parses an id against the compiled kinds and returns
 *  null for anything that is not one, so `librarainRust` and `librarianRust ` both fail — where a union
 *  only ever caught the ones a literal happened to be written for. Every call site that reads a def
 *  already had to handle `undefined` (see `useStudioPageShowing`, which absorbs exactly this case for
 *  ids arriving from component records the type system never checked). */
export type StudioId = string;

/** What a studio KIND is — everything about a studio that only code can carry, and therefore everything
 *  that stays compiled.
 *
 *  A Tauri command name, a persona id, a role gate and a workspace page are not facts any store holds:
 *  they name things that exist because someone wrote them. The TECHNOLOGY is the opposite — it is a
 *  fact the algorithms graph and the component store already answer — so it is the one field derived
 *  rather than declared. Splitting the table on that line is the whole of this change. */
export interface StudioKindDef {
  /** The id stem. A single-technology studio's id IS this; a partitioned one appends its technology. */
  kind: string;
  /** Which axis partitions this kind's store, or null when it curates everything its store holds.
   *  `librarian` reads `impl.tech` off the algorithms graph, `designer` reads `kit.tech` off the
   *  component store — one level up, which is why they are two axes and not one. */
  axis: "librarian" | "designer" | null;
  /** The stable pane id for a single-technology studio. Absent for a partitioned kind, whose pane id
   *  is derived from its technology so that adding one mints a pane rather than needing one. */
  paneId?: string;
  /** Builds the stable pane id from a technology, for a partitioned kind. */
  paneIdFor?: (tech: string) => string;
  role: SessionRole;
  setupCommand: string;
  dirKey: string;
  personaId: string;
  /** Display name in the mobile session roster (#2497). A partitioned kind appends " · <Technology>". */
  rosterName: string;
  pageKey: string;
  sectionId: string;
  defaultSkillIds?: string[];
}

/** THE COMPILED TABLE — five kinds, and no product of kind and technology.
 *
 *  This is what `SYSTEM_SESSIONS` and `STUDIO_SESSIONS` used to be eight rows of. Nothing here can be
 *  read out of a store, and nothing here varies by technology; both halves of that sentence are why
 *  this is the half that stayed. */
export const STUDIO_KINDS: readonly StudioKindDef[] = [
  {
    kind: "designer",
    axis: "designer",
    paneIdFor: designerSessionId,
    role: "designer",
    setupCommand: "setup_designer_workspace",
    dirKey: "design_dir",
    personaId: "persona-designer",
    rosterName: "Design Studio",
    pageKey: "components",
    sectionId: "designs",
    // Build components accessible + compliant BY CONSTRUCTION (#3766) — the author-time skills, not
    // the post-hoc *-audit/*-review ones the reviewer runs.
    defaultSkillIds: ["author-accessible-components", "author-compliant-components"],
  },
  {
    kind: "librarian",
    axis: "librarian",
    paneIdFor: librarianSessionId,
    role: "librarian",
    setupCommand: "setup_librarian_workspace",
    dirKey: "algorithms_dir",
    personaId: "persona-librarian",
    rosterName: "Algorithms Studio",
    pageKey: "algorithms",
    sectionId: "algorithms",
  },
  {
    kind: "architect",
    axis: null,
    paneId: TEAMS_STUDIO_SESSION_ID,
    role: "architect",
    setupCommand: "setup_architect_workspace",
    dirKey: "teams_dir",
    personaId: "persona-architect",
    rosterName: "Teams Studio",
    pageKey: "teams",
    sectionId: "teams",
  },
  {
    kind: "soundDesigner",
    axis: null,
    paneId: SOUND_STUDIO_SESSION_ID,
    role: "sound-designer",
    setupCommand: "setup_sound_designer_workspace",
    dirKey: "sound_dir",
    personaId: "persona-sound-designer",
    rosterName: "Sound Studio",
    pageKey: "sounds",
    sectionId: "sounds",
  },
  {
    kind: "integrator",
    axis: null,
    paneId: INTEGRATION_STUDIO_SESSION_ID,
    role: "integrator",
    setupCommand: "setup_integrator_workspace",
    dirKey: "integrations_dir",
    personaId: "persona-integrator",
    // `integrations` was never a Planner tab — it named a page that did not exist, so this studio's
    // dock could never report itself showing and the session could not start from a page at all. The
    // Data graph is where connectors and sources are read, so that is its home.
    rosterName: "Integration Studio",
    pageKey: "data",
    sectionId: "integrations",
    // #4023: the studio ships with its playbook — the same secret-free probe→try→register procedure
    // its spec describes, so the guidance rides with the session by construction rather than being
    // re-derived per conversation.
    defaultSkillIds: ["build-integration"],
  },
];

/** `react-native` → `ReactNative`, so a kind and a technology compose into one camel id. */
const upperCamel = (tech: string): string =>
  tech.split("-").map((p) => (p ? p[0].toUpperCase() + p.slice(1) : p)).join("");

/** The exact inverse: `ReactNative` → `react-native`.
 *
 *  It has to be an inverse rather than a lookup, because the technologies are not known here — that is
 *  the entire point of the change. Round-tripping is what lets {@link studioSessionDef} parse an id
 *  with no axis in hand, which in turn is what keeps the launch path (`studioRoleForPaneId`) free of
 *  any dependency on the axis having been read yet.
 *
 *  A HYPHEN BEFORE EVERY CAPITAL, not only before one that follows a lowercase. The obvious
 *  `/([a-z0-9])([A-Z])/` reads `AB` as `ab` where the Rust half
 *  (`bsc-session`'s `kebab`) reads it as `a-b` — so `librarianAB` resolved on one side of the wire and
 *  was refused on the other, which is precisely the silent registry drift `systemSessionRegistry.test.ts`
 *  exists to prevent and structurally cannot see (it compares kinds, not the parse). No technology in
 *  the stores has consecutive capitals, so this was only ever reachable by a hand-typed id — which is
 *  exactly what this parse is the boundary for. */
const kebab = (camel: string): string =>
  camel.replace(/(?!^)([A-Z])/g, "-$1").toLowerCase();

/** A studio session's id, from its kind and (for a partitioned kind) its technology. */
export function studioIdFor(kind: string, tech?: string): StudioId {
  return tech ? `${kind}${upperCamel(tech)}` : kind;
}

export interface StudioSessionDef {
  id: StudioId;
  /** The stable, app-owned pane id (`systemSessions.ts`) — so re-opening re-uses the SAME session. */
  paneId: string;
  /** The role gate (#219) the session launches under. Set as `paneRoles[paneId]` and NOTHING else:
   *  `restrictedRoleCommands(role)` then makes `buildSessionSettings` emit `restrictedAllow`, so the
   *  session's whole auto-run surface is its store CLI. A pane PROFILE must never be assigned — that
   *  would ADD auto-approved commands on top of the restricted surface. */
  role: SessionRole;
  /** Tauri command that creates the studio's global workspace dir + writes its spec CLAUDE.md. */
  setupCommand: string;
  /** Key on `setupCommand`'s return object holding the workspace dir (the session's cwd). */
  dirKey: string;
  /** The built-in persona whose `startPrompt` is baked into the launch as `claude --initial-message`. */
  personaId: string;
  /** Display name in the mobile session roster (#2497). */
  rosterName: string;
  /** The WORKSPACE this studio docks on (`five-graphs-become-rail-workspaces`).
   *
   *  Getting it wrong is not cosmetic: `openStudio` is the LAZY LAUNCH, so a studio whose page never
   *  reports itself as showing does not merely go unpinned for the reaper — it never starts at all. */
  pageKey: string;
  /** The section within {@link pageKey} — the tear-off signal (`detachedSections[pageKey]` containing
   *  `sectionId` ⇒ another WINDOW owns this studio's terminal). */
  sectionId: string;
  /** The TECHNOLOGY this session curates (#system-sessions-are-per-technology), for the studios whose
   *  store is partitioned. Absent for a single-technology studio (architect / sound-designer /
   *  integrator). Drives {@link studioScopeDirective}, which is what actually makes a per-tech session
   *  behave differently from its siblings. */
  tech?: string;
  /** The studio's CURATED default skill ids — resolved from the library into `paneSkills` at launch
   *  (#3766). Unlike the global-enabled firehose a normal session gets, a restricted studio session is
   *  pinned to exactly this set (absent/empty ⇒ none, preserving the confinement boundary). */
  defaultSkillIds?: string[];
}

/** The definition behind a studio kind and technology. */
function defFor(k: StudioKindDef, tech?: string): StudioSessionDef {
  return {
    id: studioIdFor(k.kind, tech),
    paneId: tech && k.paneIdFor ? k.paneIdFor(tech) : (k.paneId as string),
    role: k.role,
    setupCommand: k.setupCommand,
    dirKey: k.dirKey,
    personaId: k.personaId,
    rosterName: tech ? `${k.rosterName} · ${TECH_LABELS[tech] ?? upperCamel(tech)}` : k.rosterName,
    pageKey: k.pageKey,
    sectionId: k.sectionId,
    ...(tech ? { tech } : {}),
    ...(k.defaultSkillIds ? { defaultSkillIds: k.defaultSkillIds } : {}),
  };
}

/** Display spellings a plain capitalisation gets wrong. Absent ⇒ the derived `UpperCamel`, which is
 *  right for `rust` and `python` and everything else that is a single word. This is a LABEL table, not
 *  a roster: a technology missing from it still gets a session, just a plainer name. */
const TECH_LABELS: Record<string, string> = {
  typescript: "TypeScript",
  javascript: "JavaScript",
  "react-native": "React Native",
};

/**
 * The definition for one studio id, or null if the id names no studio.
 *
 * PURE GRAMMAR — it takes no axis, and that is deliberate. Whether a session should be OFFERED is an
 * axis question ({@link studioIds}); what a session IS, once named, is fully determined by its kind and
 * its technology. Keeping the two apart is what lets `studioRoleForPaneId` answer a confinement
 * question during launch, before anything has read a store — the failure mode on the other side of
 * that line is a studio pane reaching the launch with no role gate, which is a fully unconfined shell.
 */
export function studioSessionDef(id: StudioId | null | undefined): StudioSessionDef | null {
  if (!id) return null;
  // Longest kind first, so `designer` cannot claim an id belonging to a kind whose stem extends it.
  const kinds = [...STUDIO_KINDS].sort((a, b) => b.kind.length - a.kind.length);
  for (const k of kinds) {
    if (id === k.kind) return k.axis === null ? defFor(k) : null;
    if (!k.axis || !id.startsWith(k.kind)) continue;
    const tech = kebab(id.slice(k.kind.length));
    if (!isStudioTech(tech) || studioIdFor(k.kind, tech) !== id) continue;
    return defFor(k, tech);
  }
  return null;
}

/**
 * THE PROJECTION — every studio session that currently exists, given the technology axis.
 *
 * One row per single-technology kind, plus one per technology that kind's store actually holds. Fed
 * today's measured axis (`{librarian: ["rust", "typescript"], designer: ["react", "react-native"]}`)
 * it reproduces seven of the eight rows this replaced, ids and pane ids identical — and does not
 * produce the eighth, `librarianPython`, because no python record exists. Feed it an axis containing
 * python and the row appears, with no edit here.
 */
export function studioSessionsFor(axis: StudioAxis): StudioSessionDef[] {
  return STUDIO_KINDS.flatMap((k) =>
    k.axis === null ? [defFor(k)] : axis[k.axis].filter(isStudioTech).map((t) => defFor(k, t)),
  );
}

/** Every studio id that currently exists, in rail order. */
export function studioIds(axis: StudioAxis): StudioId[] {
  return studioSessionsFor(axis).map((d) => d.id);
}

/** Where a failed `--continue` writes its reason. Under `$BSC_LOG_DIR` (set per-pane by `pty_create`,
 *  alongside the audit/coord/perf streams), so it sits with the rest of a session's diagnostics. */
export const STUDIO_RESUME_LOG = "studio-resume.log";

/**
 * Resume the prior studio conversation across app restarts, else launch a fresh session.
 *
 * The `|| claude` fallback is deliberate — a genuinely first launch has nothing to resume. What was
 * NOT deliberate is that the old form (`claude --continue 2>/dev/null || claude`) **discarded the
 * reason** and degraded silently: a session that failed to resume looked identical to one that had
 * never run, with no log line and nothing in the pane. That made #3374 — studios starting a fresh
 * conversation across restarts — impossible to diagnose, because the one signal that would explain it
 * was being thrown away on every launch.
 *
 * So stderr now APPENDS to `$BSC_LOG_DIR/studio-resume.log` instead of `/dev/null`, and the fallback
 * announces itself in the pane. Behaviour is otherwise unchanged: resume when there is something to
 * resume, start fresh when there isn't.
 *
 * `${BSC_LOG_DIR:-/tmp}` guards the (unexpected) case of an unset log dir — a missing diagnostic must
 * never stop the session launching.
 *
 * THE HARNESS IS A PARAMETER, and it was a hardcoded `claude`. A studio pane resolves its harness
 * exactly like every other pane (`paneHarness`), so a fleet-wide local-model setting makes it
 * `bsc-agent` — and this line still launched Claude Code. That cost the session twice over: it ran
 * the wrong program, AND `pty_create` installs the SELECTED harness's shell wrapper, so there was no
 * `claude()` to emit the OSC-100 `run` marker. The backend reaper read the session as `Idle` (the
 * init line's own `__bsc_state idle` was the last word), applied the 10-second idle grace instead of
 * the 5-minute silence ceiling, and killed every architect ~20s after it opened. MEASURED:
 *
 *   11:49:00 pty[network-finance:architect] created · provider=bsc-agent · launch=claude --continue …
 *   11:49:22 [reaper] reaping idle pane network-finance:architect
 *
 * The director never had this because it launches through `LaunchPlan::Prompt`, which asks
 * `harness.launch_command` — the same reason `continueOrFresh(harness)` exists in
 * `ensureClaudeRunning`. This is the last launch line that named a harness instead of asking.
 */
export function studioInitCmd(harness: string): string {
  const h = harness.trim() || "claude";
  const log = `\${BSC_LOG_DIR:-/tmp}/${STUDIO_RESUME_LOG}`;
  return `${h} --continue 2>>"${log}"`
    + ` || { echo "[studio] no prior session resumed — starting fresh (why: ${log})"; ${h}; }`;
}

/**
 * The scoping line a per-technology studio launches with, appended to its persona prompt.
 *
 * THIS IS WHAT MAKES THE SPLIT REAL. Five sessions sharing one persona and one workspace would launch
 * identically and each would curate the whole store — the split would cost five processes and change
 * nothing. The directive names the session's technology AND the filtered read that scopes it, so the
 * session knows what it owns from its first turn.
 *
 * The two studios are scoped by DIFFERENT queries, because their stores carry `tech` at different
 * levels: an algorithms implementation carries it directly (`bsc graph impl list --tech <t>`), while a
 * component carries it via its KIT (`bsc ui kit list` → the kits whose tech matches → `--kit <id>`).
 * A single generic "filter by tech" would be wrong for one of them, so the two are written out.
 *
 * Empty for a studio with no `tech` — the architect, sound-designer and integrator curate everything
 * their store holds, and appending a scoping line that names no scope would be noise.
 */
/**
 * The line EVERY system session gets, `tech` or not: what the user is looking at is READABLE, and it
 * moves.
 *
 * Told to "simplify the graph", the designer asked which one — the tab already said, on screen, and
 * the session had no way to see it. A launch-time scope cannot fix that: it names a technology and
 * nothing finer (a technology holds many kits), it is fixed while the tab is not, and the studios
 * whose axis is NOT technology — Teams by team, Sounds by kit, Data by language — run ONE session
 * across every value, so their prompt can never name the current one.
 *
 * So the session is pointed at the live read instead of being handed a snapshot that goes stale.
 */
function viewDirective(): string {
  return (
    `## What the user is looking at

` +
    `Run \`bsc persona whatami\` to see it. The \`viewing\` line is the app's own titlebar crumb — the ` +
    `graph, its active TAB, and the entity inside it (e.g. \`Components — React — bsc-kit\`).

` +
    `READ IT BEFORE ACTING on anything phrased as "the graph", "this kit", "here" or "what I'm ` +
    `looking at". The user is pointing at the screen; the tab is the answer, and it can change while ` +
    `you run. Never guess from your start prompt — it names your technology and nothing finer, and it ` +
    `was written at launch.`
  );
}

export function studioScopeDirective(def: StudioSessionDef): string {
  if (!def.tech) return viewDirective();
  const read =
    def.role === "librarian"
      ? `Your partition is \`bsc graph impl list --tech ${def.tech}\`. Every implementation you curate, ` +
        `harvest or optimize is a ${def.tech} one.`
      : `Your partition is the kits whose \`tech\` is \`${def.tech}\` — list them with ` +
        `\`bsc ui kit list\`, then read each with \`bsc ui list --kit <kitId>\`. Every component you ` +
        `author or edit belongs to one of those kits.`;
  return (
    `## Your technology: ${def.tech}

` +
    `You are the ${def.tech} ${def.role}. ${read}

` +
    `Sibling sessions curate the other technologies — do NOT edit records outside your partition. ` +
    `A ${def.tech} artifact and its equivalent in another technology are different artifacts, not two ` +
    `copies of one, which is exactly why there is a session per technology rather than one over all ` +
    `of them.

` +
    viewDirective()
  );
}

/**
 * The studio session that curates `tech`, for a role whose store is partitioned
 * (#system-sessions-are-per-technology).
 *
 * This is how a PAGE follows its own selection: the Algorithms page's language rail and the Design
 * page's kit both already name a technology, so the dock resolves that to a session id rather than
 * holding a second selection of its own. Two selections for one concept is how they drift apart.
 *
 * Null for a technology that has no studio KIND — the dock then shows nothing rather than defaulting
 * to SOME session, because silently docking the rust librarian on a page showing go algorithms is
 * worse than an empty dock: it looks like it is working.
 *
 * It no longer consults the axis, and it does not need to. The caller is a PAGE reporting the
 * technology it is currently showing, and a page can only show a technology its store holds — so the
 * axis question has already been answered upstream by the fact that there was something to select.
 */
export function studioForTech(role: "librarian" | "designer", tech: string): StudioId | null {
  const kind = STUDIO_KINDS.find((k) => k.role === role && k.axis !== null);
  if (!kind || !isStudioTech(tech)) return null;
  return studioIdFor(kind.kind, tech);
}

/** Narrow an arbitrary string (a Glance node id, a persisted value) to a StudioId.
 *
 *  The GRAMMAR, not the axis: this guards ids arriving from persisted state and from component
 *  records, and the question those callers have is "is this a studio id at all", not "does this
 *  technology currently have records". A stale `librarianPython` in a persisted value should resolve
 *  to a def and then find no session running — the same as any studio nobody has started — rather
 *  than fail to parse and take a page down. */
export function isStudioId(value: string | null | undefined): value is StudioId {
  return studioSessionDef(value) !== null;
}

/** The studio owning a pane id, or null for any other pane (fleet, planner, debug, manual). */
export function studioForPaneId(paneId: string): StudioId | null {
  const single = STUDIO_KINDS.find((k) => k.axis === null && k.paneId === paneId);
  if (single) return single.kind;
  const per = studioPaneTech(paneId);
  return per ? studioIdFor(per.kind, per.tech) : null;
}

/**
 * The role gate a studio pane launches under, DERIVED from its pane id (#3423) — so confinement travels
 * with the session's identity instead of depending on setup having run first.
 *
 * `paneRoles[paneId]` is what makes a pane a designer, and it used to be written ONLY by
 * `seedStudioLaunchState` inside `StudioSessionMount`'s effect. That component renders only for studios in
 * `wantedStudios`, which is deliberately transient (absent from `partialize`), so after any app restart the
 * set is empty and nothing mounts. Opening a studio then created a terminal on a studio pane id with NO role
 * in the store — and `buildSessionSettings` applies no role gate, no `restrictedAllow` and no denies when it
 * finds none. The result was a fully UNCONFINED general shell on the app's most restricted surface.
 *
 * A studio's pane id is stable and app-owned, so it is sufficient on its own to establish the role. Null for
 * any other pane, where the store remains the only authority.
 */
export function studioRoleForPaneId(paneId: string): SessionRole | null {
  return studioSessionDef(studioForPaneId(paneId))?.role ?? null;
}

/**
 * Whether this studio's page is TORN OFF into its own window (#430/#463). The detached window runs its
 * OWN React root + store + TerminalHost, so it becomes the sole owner of the studio's single terminal —
 * the main window must release it (not mount a second xterm onto the same PTY, which would fight over
 * `pty_resize`). `detachedSections` is transient per-window state, so the detached window itself always
 * reads `false` here and mounts the session normally. Pure.
 */
export function studioDetached(id: StudioId, detachedSections: Record<string, string[]>): boolean {
  const def = studioSessionDef(id);
  if (!def) return false;
  return (detachedSections[def.pageKey] ?? []).includes(def.sectionId);
}

